t compensation."}, {"id": "ccf7c5c0-26c5-478a-bb74-efc1a4534592", "type": "subtopic", "title": "Economic liberties", "children": [{"id": "5c508e11-a7a6-455a-b64d-c375e4a438e5", "type": "concept", "title": "Lochner era"}, {"id": "032527b6-62b8-4b1d-98aa-8832c264e5ea", "type": "concept", "title": "New Deal shift"}, {"id": "79153218-8585-4e55-88e6-7a8ffe054178", "type": "concept", "title": "Rational basis review"}, {"id": "e6cd76cf-e5f3-4540-83a6-102bc7e1f2e2", "type": "concept", "title": "Occupational licensing debates"}], "description": "Economic liberty cases show changing judicial attitudes toward regulation and markets."}, {"id": "2ef4e7f0-4a4a-442b-acc7-e259de37e4ce", "type": "subtopic", "title": "Property and constitutional governance", "children": [{"id": "8a27b46b-70e2-427c-8f41-fb38924ff3d3", "type": "concept", "title": "Land use regulation"}, {"id": "02c9c200-9332-40a4-aaec-aaac3a134f9a", "type": "concept", "title": "Exactions"}, {"id": "7b6ca6f4-2111-4c7e-b1a1-a022e209c282", "type": "concept", "title": "Environmental regulation"}, {"id": "ed018eaf-bc69-4c5d-98e6-fe3a05c0ff4d", "type": "concept", "title": "Due process and property interests"}], "description": "Property cases connect individual rights, regulatory policy, federalism, and institutional competence."}]}, {"id": "442dafdd-8d47-4f39-aca9-61758d19ff87", "type": "topic", "title": "Contemporary Constitutional Issues, Landmark Cases, and Capstone Brief", "description": "Synthesize doctrine through current controversies, landmark cases, competing interpretive methods, and a final case brief or memo.", "children": [{"id": "21bcedfd-38b5-4029-b1c8-1ba96cf83179", "type": "subtopic", "title": "Landmark case synthesis", "children": [{"id": "3701d3e7-8177-4474-82a9-4c0446eb54a8", "type": "concept", "title": "Case timelines"}, {"id": "fe1d0100-695b-4f20-b838-43edfc3b2a2c", "type": "concept", "title": "Doctrinal tests"}, {"id": "837cab30-b501-4177-a39e-81c252b83f36", "type": "concept", "title": "Majority and dissent"}, {"id": "23e25c74-9834-44aa-bd17-94bb81fd06d0", "type": "concept", "title": "Precedent stability"}], "description": "Students learn doctrine by tracing how landmark cases build, modify, and sometimes overturn rules."}, {"id": "a7e4ac94-9119-4dcf-82e4-f8f8b2b62c26", "type": "subtopic", "title": "Contemporary controversies", "children": [{"id": "b72b2611-7444-4b6d-84c2-b98d35a714ee", "type": "concept", "title": "Voting and democracy"}, {"id": "e033b295-362b-45e0-9cee-6059b95a7b1b", "type": "concept", "title": "Abortion and reproductive rights"}, {"id": "842451be-5a3c-4113-bff2-57f3800d6958", "type": "concept", "title": "Gun rights overview"}, {"id": "877ed1c7-398a-44e4-bf9f-7403f9a89ecc", "type": "concept", "title": "Administrative state and presidential power"}], "description": "Current controversies show constitutional law as a living field shaped by courts, politics, institutions, and social movements."}, {"id": "dfc792db-7fd7-42a8-8252-74090fbdec99", "type": "subtopic", "title": "Capstone case brief or memo", "children": [{"id": "8e2d2b08-36c2-4585-a30d-2bdb19129379", "type": "concept", "title": "Question presented"}, {"id": "935d29f3-54a2-412d-b0cc-b106aebcc3d4", "type": "concept", "title": "Rule and application"}, {"id": "e362b4e3-a5aa-4ebb-b96a-d27eaac482e4", "type": "concept", "title": "Counterarguments"}, {"id": "4c599abf-0055-49fd-abe7-7d542630f7cd", "type": "concept", "title": "Policy and institutional consequences"}], "description": "The capstone turns doctrine into applied analysis and clear legal writing."}]}], "dbBacked": true}$clawjson$::jsonb,
